/**
 * FarmHash's own self-test values, extracted from `farmhash.cc` by script.
 *
 * The reference compiles with `FARMHASHSELFTEST` and checks each *namespace* individually -- which is
 * what makes them usable here, since the public `Hash64` dispatches on CPU features and is therefore
 * not reproducible. See `packages/algos/src/farmhash.ts`.
 *
 * Each entry is one 32-bit half of one hash call. `na` and `xo` make three calls per case
 * (`Hash64WithSeeds`, `Hash64WithSeed`, `Hash64`) and `uo` makes two (it has no `WithSeeds` of its own
 * in the test), so 6 and 4 values per case respectively, over 362 cases.
 *
 * **362, not 300.** FarmHash's driver has three loops where CityHash's has two: 299 cases at
 * `(offset = i * i, len = i)`, then a growth loop at `(0, i)` stepping `i += i / 7` up to a megabyte,
 * then `(0, kDataSize)`. Getting that shape wrong lines every value up against the wrong case, which is
 * why `tests/algos-farmhash.test.ts` asserts the count before comparing anything.
 *
 * The 1 MB input buffer is regenerated rather than stored -- it is CityHash's, and
 * `tests/algos-nonchash.test.ts` already builds the identical recurrence for CityHash's own vectors.
 */
export interface FarmhashSelfTest {
  readonly namespace: string;
  /** Which hash calls each case makes, in Check() order. */
  readonly calls: readonly string[];
  /** Flat 32-bit halves: high then low, per call, per case. */
  readonly expected: readonly number[];
}

